#!/usr/bin/env python3
import base64, os

files = {
    "lib/db/src/schema/finder-submissions.ts": "",
    "lib/db/src/schema/properties.ts": "",
    "artifacts/wellnest/src/pages/Home.tsx": "",
    "artifacts/wellnest/src/components/layout/Navbar.tsx": "",
    "artifacts/wellnest/src/pages/Collection.tsx": "",
    "artifacts/wellnest/src/pages/AdminDashboard.tsx": "",
    "artifacts/api-server/src/routes/admin.ts": "",
    "artifacts/wellnest/package.json": "",
}

for path, b64 in files.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        f.write(base64.b64decode(b64).decode())
    print(f'wrote {path}')
print('All done! Now run: git add -A && git commit -m "feat: buttons, admin tabs, map view, lat/lng" && git push')
